import {intakeGuidance,comparisonOverlaps} from './intake-guidance.js';
// Render/read helpers only. Persistence, authentication and authority checks belong
// to the caller and the database transaction. No form submits by itself.
import {guidance,help} from './guidance.js';
import {labReviewState,factLabel,evidenceFor} from './shared.js';
import {timingReviewState} from './timing.js';
import {priorResearchDetails} from './view-data.js';
import {renderApprovalEvidence} from './evidence-presentation.js';
export const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const PRECISIONS=['DAY','MONTH','APPROXIMATE','RANGE','UNKNOWN'];
export const STATES=['SUPPORTED','NOT_SUPPORTED','CONFLICTING','NEEDS_MORE_EVIDENCE','NOT_APPLICABLE','NOT_REVIEWED'];
export const FAMILIES={IDENTITY:['Facility identity','TEXT_WHERE_REQUIRED'],FACILITY_TYPE:['Facility type','CATEGORICAL'],KINETIC_EVENT:['Attack occurrence','BOOLEAN'],EVENT_DATE:['Event date','DATE'],ACTOR_ATTRIBUTION:['Reported actor','TEXT_WHERE_REQUIRED'],ATTACK_RELATIONSHIP:['Attack relationship','CATEGORICAL'],PHYSICAL_DAMAGE:['Physical damage','BOOLEAN'],EVACUATION:['Evacuation','BOOLEAN'],FULL_CLOSURE:['Full closure','BOOLEAN'],PARTIAL_CLOSURE:['Partial closure','BOOLEAN'],DEPARTMENT_OR_SERVICE_SHUTDOWN:['Department / service shutdown','BOOLEAN'],REDUCED_CAPACITY:['Reduced capacity','BOOLEAN'],PATIENT_TRANSFER:['Patient transfer','BOOLEAN'],UTILITY_LOSS:['Utility / power loss','BOOLEAN'],ACCESS_DISRUPTION:['Access / original-site loss','BOOLEAN'],RELOCATION:['Relocation / alternate service','BOOLEAN'],ATTACK_TO_EFFECT_CAUSATION:['Attack caused this specific effect','BOOLEAN'],EFFECT_ONSET:['Effect onset','DATE'],RESTORATION_STATUS:['Restoration status','CATEGORICAL'],RESTORATION_DATE:['Restoration date / source-reported duration','DATE'],HUMAN_IMPACT_MEASURE:['Human impact measure','QUANTITATIVE']};
const EFFECTS=['EVACUATION','FULL_CLOSURE','PARTIAL_CLOSURE','DEPARTMENT_OR_SERVICE_SHUTDOWN','REDUCED_CAPACITY','PATIENT_TRANSFER','UTILITY_LOSS','ACCESS_DISRUPTION','RELOCATION'];
const LABELS={SUPPORTED:'Supported',NOT_SUPPORTED:'Not Supported',CONFLICTING:'Conflicting',NEEDS_MORE_EVIDENCE:'Needs More Evidence',NOT_APPLICABLE:'Not Applicable',NOT_REVIEWED:'Not Reviewed'};
const copy=v=>v===undefined?null:JSON.parse(JSON.stringify(v));
const text=v=>Array.isArray(v)?v.map(text).join('; '):v&&typeof v==='object'?Object.entries(v).map(([k,x])=>`${k.replaceAll('_',' ')}: ${text(x)}`).join('; '):v===null||v===undefined?'Unknown':v===true?'Yes':v===false?'No':String(v);
const options=(rows,current)=>rows.map(row=>{const [value,label]=Array.isArray(row)?row:[row,row];return `<option value="${h(value)}" ${value===current?'selected':''}>${h(label)}</option>`}).join('');
const field=(label,control,full=false)=>`<div class="field${full?' full':''}"><label${/id="([^"]+)"/.test(control)?' for="'+control.match(/id="([^"]+)"/)[1]+'"':''}>${h(label)}</label>${control}</div>`;
const input=(name,value='',type='text',extra='')=>`<input name="${h(name)}" id="${h(name)}" type="${type}" value="${h(value)}" ${extra}>`;
const area=(name,value='',extra='')=>`<textarea name="${h(name)}" id="${h(name)}" ${extra}>${h(value)}</textarea>`;
const requiredText='data-required-text="true"';
const select=(name,rows,value='',extra='')=>`<select name="${h(name)}" id="${h(name)}" ${extra}>${options(rows,value)}</select>`;
const data=form=>form&&typeof form.get==='function'&&typeof form.entries==='function'?form:new (form?.ownerDocument?.defaultView?.FormData||FormData)(form);
const value=(fd,name)=>String(fd.get(name)??'').trim();
const required=(fd,name,label)=>{const v=value(fd,name);if(!v)throw Error(`Enter ${label}, or explicitly say Unknown where appropriate.`);return v;};
const parseDay=s=>/^\d{4}-\d{2}-\d{2}$/.test(s)&&Number.isFinite(Date.parse(s+'T00:00:00Z'))&&new Date(s+'T00:00:00Z').toISOString().slice(0,10)===s;

export function renderDate(prefix,date={value:null,precision:'UNKNOWN'},label='Date'){
 const precision=PRECISIONS.includes(date?.precision)?date.precision:'UNKNOWN',v=date?.value;
 return `<fieldset class="date-control" data-date-prefix="${h(prefix)}"><legend>${h(label)}</legend>${guidance(prefix+'-date-precision','<b>Use the most precise date the evidence supports — no more.</b> Do not invent a day to complete the form.')}${help(prefix+'-date-precision-help','Which date precision should I use?','<p>Exact day → Exact day. Only a month known → Month only. “Around July” → Approximate. A period spanning dates → Date range. Not established → Unknown.</p>')}${field('How precisely is the date known?',select(prefix+'-precision',PRECISIONS.map(p=>[p,p==='UNKNOWN'?'Unknown':p==='APPROXIMATE'?'Approximate':p==='RANGE'?'Date range':p==='MONTH'?'Month only':'Exact day']),precision,'data-date-precision'))}<div data-date-kind="DAY" ${precision==='DAY'?'':'hidden'}>${field('Exact date',input(prefix+'-day',precision==='DAY'?v||'':'','date',requiredText))}</div><div data-date-kind="MONTH" ${precision==='MONTH'?'':'hidden'}>${field('Month — no day is assumed',input(prefix+'-month',precision==='MONTH'?v||'':'','month',requiredText))}</div><div data-date-kind="APPROXIMATE" ${precision==='APPROXIMATE'?'':'hidden'}>${field('Approximate date or period',input(prefix+'-approximate',precision==='APPROXIMATE'?typeof v==='string'?v:text(v):'','text',requiredText+' placeholder="For example: around mid-May 2026"'))}</div><div data-date-kind="RANGE" class="form-grid" ${precision==='RANGE'?'':'hidden'}>${field('Range start',input(prefix+'-start',precision==='RANGE'?v?.start||'':'','date',requiredText))}${field('Range end',input(prefix+'-end',precision==='RANGE'?v?.end||'':'','date',requiredText))}</div><p data-date-kind="UNKNOWN" ${precision==='UNKNOWN'?'':'hidden'}>The date will remain Unknown. No day or duration is inferred.</p></fieldset>`;
}
export function readDate(form,prefix){
 const fd=data(form),precision=value(fd,prefix+'-precision')||'UNKNOWN';
 if(!PRECISIONS.includes(precision))throw Error('Choose an available date precision.');
 if(precision==='UNKNOWN')return {value:null,precision};
 if(precision==='DAY'){const v=value(fd,prefix+'-day');if(!parseDay(v))throw Error('Enter a valid exact date or choose Unknown.');return {value:v,precision};}
 if(precision==='MONTH'){const v=value(fd,prefix+'-month');if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(v))throw Error('Enter a year and month without inventing a day.');return {value:v,precision};}
 if(precision==='APPROXIMATE')return {value:required(fd,prefix+'-approximate','the approximate date or period'),precision};
 const start=value(fd,prefix+'-start'),end=value(fd,prefix+'-end');
 if(!parseDay(start)||!parseDay(end)||end<start)throw Error('Enter valid range bounds in order, or choose Unknown.');
 return {value:{start,end},precision};
}

const SOURCE_KINDS=[['news','News article'],['official','Official statement'],['hospital','Hospital statement'],['humanitarian','Humanitarian report'],['social','Social-media post'],['video','Video'],['photo','Photograph'],['mapping','Geolocation / mapping evidence'],['human OSINT','Human research observation'],['other','Other']];
export function renderSource(prefix='source',initial={}){
 const s=initial.source||initial,r=initial.relation||{},social=s.social_fields||{},cp=s.content_preservation_status||{};
 const first=Array.isArray(r.evidence_locator)?r.evidence_locator[0]||{}:{};
 const kind=cp.source_description||s.source_type||'news';
 return `<section class="source-intake" data-source-prefix="${h(prefix)}"><h3>Source information</h3>${guidance(prefix+'-source-task','<b>Read the source itself and decide how it relates to this fact.</b> Record the relevant passage or what you can actually see.')}${guidance(prefix+'-publication-date','Publication / post date describes the source, not when the incident happened.',{warn:true})}<div class="form-grid">${field('Source type',select(prefix+'-type',SOURCE_KINDS,kind,'data-source-kind'))}${field('URL or preserved identifier',input(prefix+'-url',s.original_url||'','text','required'))}${field('Source title',input(prefix+'-title',s.title||'','text','required'))}${field('Publisher or account',input(prefix+'-publisher',s.publisher_platform||'','text','required'))}<div class="field full">${renderDate(prefix+'-publication',s.publication_date||{},'Publication / post date')}</div>${field('How does this relate to the fact?',select(prefix+'-relationship',[['','Choose how this source relates to this fact…'],['SUPPORTS','Supports this finding'],['CONTRADICTS','Challenges this finding'],['LIMITS','Qualifies this finding'],['CONTEXT_ONLY','Provides background']],r.support_direction||'','required')+help(prefix+'-relationship-help','What do these evidence relationships mean?','<p>Choose the relationship to the exact displayed proposition. <b>Supports this finding:</b> a photograph of broken windows supports “This facility sustained physical damage.” It does not establish “This facility fully closed.” <b>Challenges this finding:</b> a documented open service contradicts closure of that same service at that time. <b>Qualifies this finding:</b> an account limited to one ward cannot establish closure of the entire facility. <b>Provides background:</b> regional conditions provide background without establishing this facility’s closure.</p>'))}${field('Where exactly is the evidence?',input(prefix+'-locator',first.locator||first.value||'','text','required placeholder="Page, paragraph, timestamp, image/frame, section"'))}${field('Relevant passage or visual description',area(prefix+'-excerpt',first.excerpt||cp.excerpt||'','required'),true)}${field('Important limitations',area(prefix+'-limitations',r.limitations||s.limitations||'','required placeholder="Access, date, location, identity or other limits. State none known if appropriate."'),true)}</div><details class="secondary-details"><summary>Source details: access, originality and preservation</summary><div class="secondary-content">${guidance(prefix+'-source-dependency','You can attach more than one source to the same fact. Several articles repeating the same underlying report may not be independent confirmation; record what you know and leave uncertain details Unknown.')}<div class="form-grid">${field('Did you view the original source?',select(prefix+'-access',[['UNKNOWN','Unknown'],['USABLE_BODY','Yes — complete source'],['PARTIAL_USABLE_BODY','Yes — only part available'],['INDEXED_ONLY','Search/index result only'],['INACCESSIBLE_NEUTRAL','Source inaccessible'],['DUPLICATE_OR_DEPENDENT','Only a repeated/dependent copy']],s.retrieval_body_status||'UNKNOWN'))}${field('How directly does it establish this fact?',select(prefix+'-directness',[['unknown','Unknown'],['direct','Directly reports or depicts it'],['secondary','Reports another source’s account'],['inferred','An inference, not explicitly reported'],['indexed-only','Index/search excerpt only'],['contextual','Background context only']],r.directness||'unknown'))}${field('Is this original reporting?',select(prefix+'-originality',[['unknown','Unknown'],['original','Original reporting'],['republication','Republication'],['syndication','Syndicated report'],['repost','Repost']],r.originality||'unknown'))}${field('Does it rely on another report?',select(prefix+'-relies',[['unknown','Unknown'],['yes','Yes'],['no','No known reliance']],r.dependency_provenance?.relies_on||'unknown'))}${field('Underlying report or source, if known',input(prefix+'-underlying',r.dependency_provenance?.underlying||'','text','placeholder="Source ID, URL, title, or Unknown"'),true)}${field('Explain whether it is independent or repeated',area(prefix+'-dependency',r.dependency_provenance?.independence||'','placeholder="Unknown is acceptable; source count does not establish independence."'),true)}${field('How was the source preserved or recorded? (optional)',area(prefix+'-preservation',cp.preservation||'','placeholder="Optional: saved excerpt, screenshot identifier or archive URL"')+'<p class="subtle">Leave blank if no preservation method was recorded. It will be saved as Not recorded; this does not mean preserved or not preserved.</p>',true)}${field('Is the complete source available?',select(prefix+'-complete',[['unknown','Unknown'],['complete','Complete'],['partial','Partial'],['unavailable','Unavailable']],cp.completeness||'unknown'))}</div></div></details><fieldset data-social-fields ${kind==='social'?'':'hidden'}><legend>Social-media details</legend>${guidance(prefix+'-social-entry','Enter the details you checked manually. Use Unknown or Unverified when you cannot confirm the account, date, location, or facility match.')}<div class="form-grid">${field('Platform',input(prefix+'-platform',social.platform||'Unknown','text',requiredText))}${field('Account',input(prefix+'-account',social.account||'Unknown','text',requiredText))}${field('Post ID / URL',input(prefix+'-post',social.post_id||'Unknown','text',requiredText))}${field('Post timestamp status',select(prefix+'-timestamp-status',[['unknown','Unknown'],['recorded','Recorded'],['approximate','Approximate']],social.timestamp_status||'unknown'))}${field('Post time and timezone, if known',input(prefix+'-time',social.post_timestamp||'Unknown','text',requiredText))}${field('Location check',select(prefix+'-geo',[['unverified','Unverified'],['supported','Supported by recorded evidence'],['conflicting','Conflicting'],['unknown','Unknown']],social.geo_status||'unverified'))}${field('Date / chronology check',select(prefix+'-chronology',[['unverified','Unverified'],['supported','Supported by recorded evidence'],['conflicting','Conflicting'],['unknown','Unknown']],social.chronology_status||'unverified'))}${field('Does it match this facility / incident?',select(prefix+'-match',[['unverified','Unverified'],['supported','Supported by recorded evidence'],['conflicting','Conflicting'],['unknown','Unknown']],social.facility_match||social.facility_incident_match||'unverified'))}${field('Social-source preservation notes',area(prefix+'-social-preservation',social.preservation||social.preservation_notes||'Unknown',requiredText),true)}</div></fieldset><label class="field section-space"><input type="checkbox" name="${h(prefix)}-material" ${initial.material||r.support_direction==='LIMITS'||r.support_direction==='CONTRADICTS'?'checked':''}> This evidence could change the current finding. Review the fact again.</label>${field('If qualifying evidence does not affect the current finding, explain why',area(prefix+'-material-reason',initial.material_reason||''),true)}</section>`;
}
export function readSource(form,prefix='source',options={}){
 const fd=data(form),get=s=>value(fd,prefix+'-'+s),kind=get('type');
 if(!options.reuse&&!SOURCE_KINDS.some(([v])=>v===kind))throw Error('Choose a source type.');
 const relationship=get('relationship');if(!['SUPPORTS','CONTRADICTS','LIMITS','CONTEXT_ONLY'].includes(relationship))throw Error('Choose how the source relates to the fact.');
 const locator=required(fd,prefix+'-locator','the exact evidence location'),excerpt=required(fd,prefix+'-excerpt','the relevant passage or visual description'),limits=required(fd,prefix+'-limitations','the source limitations');
 const directness=get('directness');if(!['unknown','direct','secondary','inferred','indexed-only','contextual'].includes(directness))throw Error('Choose how directly this source supports the fact.');
 const underlying=get('underlying')||null;if(get('relies')==='yes'&&!underlying)throw Error('Identify the report this source relies on, or enter Unknown.');
 const preservation=options.reuse?null:get('preservation')||'Not recorded';
 const source=options.reuse?null:{source_type:{hospital:'official',video:'other',photo:'other'}[kind]||kind,title:required(fd,prefix+'-title','the source title'),publisher_platform:required(fd,prefix+'-publisher','the publisher/account'),original_url:required(fd,prefix+'-url','the URL or identifier'),canonical_url:null,publication_date:readDate(fd,prefix+'-publication'),retrieval_body_status:get('access')||'UNKNOWN',retrieval_date:null,content_preservation_status:{excerpt,preservation,access:get('access')||'UNKNOWN',completeness:get('complete')||'unknown',source_description:kind},evidence_locator:[{locator,excerpt}],limitations:limits,social_fields:null};
 if(!options.reuse&&kind==='social')source.social_fields={platform:required(fd,prefix+'-platform','the platform'),account:required(fd,prefix+'-account','the account or Unknown'),post_id:required(fd,prefix+'-post','the post ID/URL or Unknown'),post_timestamp:get('time')==='Unknown'?null:required(fd,prefix+'-time','the post time or Unknown'),timestamp_status:required(fd,prefix+'-timestamp-status','the timestamp status'),publication_date:copy(source.publication_date),access:source.retrieval_body_status,originality:get('originality')||'unknown',geo_status:get('geo')||'unverified',chronology_status:get('chronology')||'unverified',facility_match:get('match')||'unverified',preservation:required(fd,prefix+'-social-preservation','social preservation notes'),limitations:limits};
 const relation={support_direction:relationship,directness:directness==='unknown'?null:directness,originality:get('originality')||'unknown',dependency_group_id:null,dependency_provenance:{relies_on:get('relies')||'unknown',underlying,independence:get('dependency')||'Unknown'},evidence_locator:[{locator,excerpt}],limitations:limits};
 if(!options.reuse&&kind==='social'&&get('timestamp-status')!=='unknown'&&(!get('time')||get('time')==='Unknown'))throw Error('Enter the recorded or approximate post time, or choose Unknown timestamp status.');
 const material=relationship==='CONTRADICTS'||fd.has(prefix+'-material'),materialReason=get('material-reason')||null;
 if(relationship==='LIMITS'&&!material&&!materialReason)throw Error('Explain why this limitation does not change the current finding, or mark it for review.');
 return {source,relation,material,material_reason:materialReason};
}

function categories(claim){
 const rows=[['__UNKNOWN__','Unknown / not established']],family=claim.claim_family;
 if(family==='FACILITY_TYPE')rows.push(['hospital','Hospital'],['primary_health_care_center','Primary health care center'],['primary_health_care_center_medical_clinic','Primary health care center / medical clinic']);
 if(family==='ATTACK_RELATIONSHIP')rows.push(['EXACT_TARGET','Exact target'],['NEARBY_CONTEXT','Nearby / context'],['REJECTED','Relationship rejected by evidence']);
 if(family==='RESTORATION_STATUS')rows.push(['not_found','No restoration evidence found — not proof of no restoration']);
 const v=claim.current_verified_value??claim.proposed_value;
 if(v!==null&&v!==undefined&&!rows.some(([id])=>id===String(v)))rows.push(['__CURRENT__','Keep current recorded value: '+text(v)]);
 return rows;
}
export function renderTyped(prefix='fact',claim={}){
 const family=claim.claim_family||'KINETIC_EVENT',type=claim.value_type||FAMILIES[family]?.[1]||'TEXT_WHERE_REQUIRED',v=Object.hasOwn(claim,'current_verified_value')?claim.current_verified_value:claim.proposed_value??null;
 let content='';
 if(['DATE','DATE_RANGE'].includes(type))content=renderDate(prefix+'-date',{value:v,precision:claim.date_precision||(type==='DATE_RANGE'?'RANGE':'UNKNOWN')},'Fact date / period');
 else if(type==='BOOLEAN')content=field('Value',select(prefix+'-value',[['__UNKNOWN__','Unknown'],['true','Yes'],['false','No']],v===true?'true':v===false?'false':'__UNKNOWN__'));
 else if(type==='QUANTITATIVE')content=`<div class="form-grid">${field(family==='RESTORATION_DATE'?'Source-reported duration':'Number — leave blank when unknown',input(prefix+'-value',v??'','number','step="any"'))}${field('Unit',input(prefix+'-unit',claim.quantitative_unit||'','text',requiredText))}${field('Evidence basis',select(prefix+'-basis',[['','Unknown'],['directly reported','Directly reported'],['context/capacity','Baseline / capacity context'],['proxy/estimated','Proxy / estimate']],claim.impact_basis||''))}</div>${family==='RESTORATION_DATE'?guidance(prefix+'-source-duration','<b>Record a duration only when the source states it.</b> Do not calculate it from dates here. A source-stated duration and one calculated from verified start/end dates are different; if neither is established, leave duration unknown.',{warn:true}):''}`;
 else if(type==='CATEGORICAL'){const rows=categories(claim),selected=v===null?'__UNKNOWN__':rows.some(([x])=>x===String(v))?String(v):'__CURRENT__';content=field('Value',select(prefix+'-value',rows,selected));if(family==='FACILITY_TYPE')content+=field('Type as described by the source — preserve an unmapped description here',input(prefix+'-source-type',claim.source_described_type||''));}
 else if(v&&typeof v==='object')content=`<p>Current detailed value: ${h(text(v))}</p>${field('Keep or propose a replacement',select(prefix+'-replace',[['keep','Keep the complete current value'],['replace','Propose a new plain-language value']],'keep'))}${field('Replacement value, only if selected above',area(prefix+'-value',''))}`;
 else content=field('Value — leave blank when unknown',area(prefix+'-value',v??''));
 const method=family==='PHYSICAL_DAMAGE'||family==='FULL_CLOSURE'?'<b>Physical damage does not automatically mean the facility stopped providing healthcare.</b> Review physical damage and service disruption separately.':family==='EVACUATION'?'<b>Evacuation does not automatically mean full closure.</b> Record only the people or services the evidence says were evacuated.':['PARTIAL_CLOSURE','DEPARTMENT_OR_SERVICE_SHUTDOWN','REDUCED_CAPACITY','UTILITY_LOSS','ACCESS_DISRUPTION','RELOCATION','PATIENT_TRANSFER'].includes(family)?'Record the specific service, site, or degree of disruption that the source actually establishes. Do not turn a partial or site-specific effect into full closure.':family==='ATTACK_RELATIONSHIP'?'<b>Check what the source actually says was struck.</b> A nearby strike is not the same as a strike on the facility.':family==='ATTACK_TO_EFFECT_CAUSATION'?'<b>Proximity alone does not prove that the attack caused the operational effect.</b> Check the evidence linking this attack to this specific effect.':'';
 return `<div class="typed-control" data-typed-prefix="${h(prefix)}" data-family="${h(family)}" data-value-type="${h(type)}">${method?`<div class="fact-method-guidance">${guidance(prefix+'-method',method,{warn:true})}</div>`:''}${content}${guidance(prefix+'-unknown','<b>If the evidence does not answer the question, choose Unknown or Needs More Evidence.</b> Do not turn missing information into “No.”',{warn:true})}</div>`;
}
export function readTyped(form,prefix='fact',claim={}){
 const fd=data(form),family=claim.claim_family,type=claim.value_type||FAMILIES[family]?.[1],old=Object.hasOwn(claim,'current_verified_value')?claim.current_verified_value:claim.proposed_value??null;
 let v=null,precision=claim.date_precision??null,unit=claim.quantitative_unit??null,basis=claim.impact_basis??null,actualType=type;
 if(['DATE','DATE_RANGE'].includes(type)){const d=readDate(fd,prefix+'-date');v=d.value;precision=d.precision;actualType=d.precision==='UNKNOWN'?type:d.precision==='RANGE'?'DATE_RANGE':'DATE';}
 else if(type==='BOOLEAN'){const x=value(fd,prefix+'-value');if(!['true','false','__UNKNOWN__'].includes(x))throw Error('Choose Yes, No, or Unknown.');v=x==='true'?true:x==='false'?false:null;}
 else if(type==='QUANTITATIVE'){const x=value(fd,prefix+'-value');v=x===''?null:Number(x);unit=value(fd,prefix+'-unit')||null;basis=value(fd,prefix+'-basis')||null;if(!unit)throw Error('Record the unit for this quantity even if its number is unknown.');if(v!==null&&!Number.isFinite(v))throw Error('Enter a valid number, or leave the number unknown.');if(family==='RESTORATION_DATE'&&v!==null&&(v<0||basis!=='directly reported'))throw Error('A recorded duration needs a nonnegative number, unit, and directly reported source basis. Keep estimates or calculations in notes.');}
 else if(type==='CATEGORICAL'){const x=value(fd,prefix+'-value');if(!categories(claim).some(([id])=>id===x))throw Error('Choose a value from this fact’s choices.');v=x==='__UNKNOWN__'?null:x==='__CURRENT__'?copy(old):x;}
 else if(old&&typeof old==='object'&&value(fd,prefix+'-replace')!=='replace')v=copy(old);
 else v=value(fd,prefix+'-value')||null;
 return {value:v,value_type:actualType,date_precision:precision,quantitative_unit:unit,impact_basis:basis,...(family==='FACILITY_TYPE'?{source_described_type:value(fd,prefix+'-source-type')||null}:{})};
}

function causeFields(claim,claims){
 if(claim.claim_family!=='ATTACK_TO_EFFECT_CAUSATION')return '';
 const current=claims.filter(c=>c.is_current!==false&&(!claim.incident_id||c.incident_id===claim.incident_id)),attacks=current.filter(c=>c.claim_family==='KINETIC_EVENT'),effects=current.filter(c=>EFFECTS.includes(c.claim_family));
 return `<fieldset class="callout"><legend>Which attack caused which effect?</legend><p>Select the exact attack fact and the exact effect fact. Evidence that an attack caused evacuation does not establish that it caused full closure.</p>${field('Attack fact',select('attack_claim_id',[['','Choose the attack fact…'],...attacks.map(c=>[c.claim_id,c.subject])],claim.attack_claim_id||''))}${field('Specific effect fact',select('effect_claim_id',[['','Choose the effect fact…'],...effects.map(c=>[c.claim_id,`${FAMILIES[c.claim_family]?.[0]} — ${c.subject}`])],claim.effect_claim_id||''))}</fieldset>`;
}
function primaryIdentity(claim){return claim.claim_family==='IDENTITY'&&claim.facility_id&&['BOOLEAN','TEXT_WHERE_REQUIRED'].includes(claim.value_type)&&Array.isArray(claim.legacy_refs)&&claim.legacy_refs.length===0&&claim.ai_original_value==null&&!String(claim.validation_origin||'').startsWith('LEGACY_')&&(claim.primary_facility_identity===true||/physical facility|facility identity|facility name/i.test(claim.subject||''));}
function identityFields(claim){return primaryIdentity(claim)?`<div class="callout warning"><b>Check this physical facility</b><p>This review checks the facility-name proposition only. It does not settle a possible duplicate. Use Facility / identity review → Review identity / possible duplicate for an evidence-backed Same physical facility, Different physical facility, or Not sure yet decision. The dedicated workflow preserves both records and their history.</p></div>`:'';}

export const approvalRationaleMessage='Explain how the selected evidence supports approval despite the recorded challenges or qualifications.';
export function reviewBasisNeedsExplanation(s,claimId){
 return Boolean(s.records&&evidenceFor(s,claimId).some(({relation})=>['CONTRADICTS','LIMITS'].includes(relation.support_direction)));
}

export function factForm(claim,claims=[],s={},pending){
 const labState=labReviewState(claim,s), lab=s.workflow?.claims?.[claim.claim_id]||{}, preserved=String(claim.validation_origin||'').startsWith('LEGACY_');
 const needsExplanation=reviewBasisNeedsExplanation(s,claim.claim_id);
 const basisField=field(needsExplanation?'If Supported, explain why the selected evidence is sufficient despite the challenges or qualifications':'Explain competing accounts or any exception to the usual source support',area('basis_explanation','',needsExplanation&&claim.validation_state==='SUPPORTED'?'required':''),true);
 const reviewGuidance=labState==='REVIEWED'?'<b>This fact has been reviewed by the current lab.</b> Change it only if the evidence supports a different conclusion.':labState==='REOPENED'?'<b>Lab review reopened.</b> Review the new evidence. The earlier lab review remains preserved.':preserved?'<b>Needs lab validation.</b> Review the prior research and saved evidence before certifying a decision. Historical human review does not satisfy current-lab validation.':'<b>Needs lab validation.</b> Adding this fact did not validate it. Review its saved evidence before certifying a decision; the person who added it may perform this review.';
 const stateGuidance=claim.validation_state==='CONFLICTING'?'<b>The sources disagree.</b> Review both accounts. Do not choose one simply because it appears first.':claim.validation_state==='NEEDS_MORE_EVIDENCE'?'<b>The current evidence is not enough to determine this fact.</b> Check the sources and use What Still Needs Checking for the next research task.':'';
 return `<form id="fact-form" data-form-kind="fact" data-approval-rationale-required="${needsExplanation}"><h2 class="fact-type">${h(claim.claim_family==='IDENTITY'?factLabel(claim):FAMILIES[claim.claim_family]?.[0]||claim.claim_family)}</h2><p class="fact-proposition">${h(claim.subject)}</p><div class="review-context"><div><div class="label">Current evidence assessment</div><div class="value"><b>${h(LABELS[claim.validation_state]||'Not Reviewed')}</b></div></div><div><div class="label">${labState==='NOT_REVIEWED'&&preserved?'Prior research finding':'Current verified value'}</div><div class="value"><b>${h(text(claim.current_verified_value))}</b>${claim.date_precision?' · '+h(claim.date_precision):''}${claim.quantitative_unit?' '+h(claim.quantitative_unit):''}${claim.impact_basis?' · '+h(claim.impact_basis):''}</div></div></div><div class="fact-state-guidance"><p><b>Current lab validation:</b> ${h(timingReviewState(s,claim))}${lab.lab_reviewed_by?' · '+h(lab.lab_reviewed_by):''}${lab.lab_reviewed_at?' · '+h(lab.lab_reviewed_at):''}</p>${guidance('fact-human-review',reviewGuidance)}${stateGuidance?guidance('fact-evidence-context',stateGuidance,{warn:claim.validation_state==='CONFLICTING'}):''}</div><div class="callout task-guidance"><b>Your task</b><br>Check the source passages and decide what this exact proposition establishes. Follow any linked research instruction. Your factual review does not complete the incident.</div><div class="form-grid section-space"><div class="field full">${renderTyped('fact',claim)}</div>${field('Review result — what does the evidence show?',select('validation_state',STATES.map(s=>[s,LABELS[s]]),claim.validation_state||'NOT_REVIEWED'))}<div class="field full">${causeFields(claim,claims)}${identityFields(claim)}</div>${field('Reviewer notes / limitations',area('review_notes',claim.review_notes||'','required'),true)}${basisField}</div>${renderApprovalEvidence(s,claim,pending)}<details class="secondary-details"><summary>Original research value and review provenance</summary><div class="secondary-content">${priorResearchDetails(s,claim)}${claim.ai_original_provenance||String(claim.validation_origin).startsWith('LEGACY_AI')?guidance('fact-ai-origin','<b>AI-assisted discovery means the system surfaced this possible finding or source.</b> It still needs human assessment before it counts as human-reviewed. Research origin and human review are separate.'):''}</div></details><div class="certification-box"><label><input type="checkbox" name="attestation" required> I checked this fact, its value, evidence, and limitations.</label></div><p class="form-error" role="alert" hidden></p><div class="dialog-actions"><span class="subtle">Private proposal until you review and submit.</span><button class="primary" type="submit">Add review to changes</button></div></form>`;
}

export function readFact(form,claim){
 const fd=data(form),typed=readTyped(fd,'fact',claim),state=value(fd,'validation_state');if(!STATES.includes(state)||state==='NOT_REVIEWED')throw Error('Choose a factual review result. Use a private draft if you are not ready to decide.');
 const notes=required(fd,'review_notes','your review notes');if(!fd.has('attestation'))throw Error('Confirm that you checked the fact and evidence.');
 const cause=claim.claim_family==='ATTACK_TO_EFFECT_CAUSATION'?{attack_claim_id:value(fd,'attack_claim_id')||null,effect_claim_id:value(fd,'effect_claim_id')||null}:{};
 if(claim.claim_family==='ATTACK_TO_EFFECT_CAUSATION'&&state==='SUPPORTED'&&typed.value===true&&(!cause.attack_claim_id||!cause.effect_claim_id))throw Error('A supported causal finding must name the exact attack and effect facts.');
 const basis_explanation=value(fd,'basis_explanation')||null;
 let approval={};
 if(state==='SUPPORTED'){
  if(form.dataset.unsubmittedEvidence==='true')throw Error('Submit the pending evidence for this fact first, then reopen the review and choose its approval evidence.');
  const selected=new Set(fd.getAll('approval_evidence_choice'));
  if(!selected.size)throw Error('Select at least one supporting evidence relationship for approval.');
  if(form.dataset.approvalRationaleRequired==='true'&&!basis_explanation)throw Error(approvalRationaleMessage);
  const revision=value(fd,'approval_fact_revision');
  if(!revision)throw Error('The fact revision is unavailable. Reopen the review.');
  const approval_evidence=JSON.parse(value(fd,'approval_evidence_baseline')).map(ref=>({...ref,selected:selected.has(ref.id)}));
  approval={expected_claim_revision:Number(revision),approval_evidence};
 }
 return {claim_id:claim.claim_id,...typed,validation_state:state,review_notes:notes,basis_explanation,attestation:true,...cause,...approval};
}

export function newFactForm(claims=[],prefill={}){
 const family=Object.hasOwn(FAMILIES,prefill.family)?prefill.family:'KINETIC_EVENT';
 const duration=family==='RESTORATION_DATE'&&prefill.value_type==='QUANTITATIVE';
 const initial={claim_family:family,value_type:duration?'QUANTITATIVE':FAMILIES[family][1],proposed_value:null,quantitative_unit:duration?'days':null,impact_basis:duration?'directly reported':null};
 const mode=family==='RESTORATION_DATE'?field('What does the source report?',select('duration_mode',[['date','Restoration / end date'],['duration','Duration explicitly reported by a source']],duration?'duration':'date','data-duration-mode')):'';
 return `<form id="new-fact-form" data-form-kind="new-fact" data-next-source="2">${guidance('new-fact-task','<b>Use this for a factual question not already represented in the incident.</b> Add one clear proposition at a time. You can attach evidence now or later.')}${help('new-fact-or-evidence','Should I add a new fact or add evidence?','<p>If the source supports, contradicts, limits, or adds context to an existing fact, add evidence to that fact instead. Use a new fact only for a different question; do not combine several conclusions into one.</p>')}<div class="callout"><b>Initial entry — needs validation</b><br>Adding a fact records the proposition in the case. It does not establish a verified finding. Review it through the normal Fact Validation workflow when evidence is available.</div><div class="form-grid section-space">${field('Type of fact',select('claim_family',Object.entries(FAMILIES).map(([v,[label]])=>[v,label]),family,'data-new-family'))}${field('What factual proposition or question are you adding?',area('subject','','required'),true)}${field('How is this different from the existing facts?',area('distinct_reason','','required'),true)}<div class="field full"><b>Initial value — optional, not verified</b><p class="subtle">Leave Unknown if you do not have an initial value. An entry here is kept separately from the verified finding until an explicit fact review.</p></div><div class="field full" data-new-typed>${mode}${renderTyped('new-fact',initial)}</div><div class="field full" data-cause-container>${causeFields(initial,claims)}</div></div><h3 class="section-space">Initial evidence — optional</h3><p class="subtle">Use the same source details as Add Evidence. You may add one or more sources now, or add them to the fact later.</p><label class="section-space"><input type="checkbox" name="include_initial_evidence" data-new-fact-evidence-toggle> Add initial evidence</label><fieldset data-new-fact-evidence disabled hidden><div data-initial-sources>${initialSourceCard('new-source',1)}</div><button type="button" data-add-initial-source>+ Add another source</button></fieldset><p class="callout" data-no-initial-evidence><b>Needs evidence · Needs lab validation</b><br>Without an attached source, the fact enters the case ready for evidence collection. It cannot become Supported without evidence and an explicit review.</p><p class="form-error" role="alert" hidden></p><div class="dialog-actions"><span class="subtle">Check the entry before adding it to the case.</span><button class="primary" type="submit">Review fact entry</button></div><script type="application/json" data-form-claims>${JSON.stringify(claims).replaceAll('<','\\u003c')}</script></form>`;
}

function initialSourceCard(prefix,number){
 return `<fieldset class="section-space" data-initial-source="${h(prefix)}"><legend>Initial source <span data-initial-source-number>${number}</span></legend><input type="hidden" name="initial_source_prefix" value="${h(prefix)}">${renderSource(prefix)}<button type="button" data-remove-initial-source="${h(prefix)}">Remove source from this submission</button></fieldset>`;
}

function setInitialEvidence(form,enabled){
 const pane=form.querySelector('[data-new-fact-evidence]');
 if(enabled&&!pane.querySelector('[data-initial-source]'))pane.querySelector('[data-initial-sources]').innerHTML=initialSourceCard('new-source',1);
 pane.hidden=!enabled;pane.disabled=!enabled;
 form.querySelector('[data-no-initial-evidence]').hidden=enabled;
 form.querySelector('[data-new-fact-evidence-toggle]').checked=enabled;
}

export function readNewFact(form){
 const fd=data(form),family=value(fd,'claim_family');if(!FAMILIES[family])throw Error('Choose a type of fact.');
 const type=family==='RESTORATION_DATE'&&value(fd,'duration_mode')==='duration'?'QUANTITATIVE':FAMILIES[family][1],typed=readTyped(fd,'new-fact',{claim_family:family,value_type:type,proposed_value:null});
 const prefixes=fd.has('include_initial_evidence')?fd.getAll('initial_source_prefix'):[];
 if(fd.has('include_initial_evidence')&&!prefixes.length)throw Error('Add an initial source or choose to add the fact without evidence.');
 if(prefixes.some(p=>!/^new-source(?:-[2-9]\d*|-[1-9]\d+)?$/.test(p))||new Set(prefixes).size!==prefixes.length)throw Error('Check the initial source entries before continuing.');
 const evidence=prefixes.map(prefix=>readSource(fd,prefix));
 return {claim:{claim_family:family,subject:required(fd,'subject','the factual proposition'),value_type:typed.value_type,proposed_value:typed.value,current_verified_value:null,ai_original_value:null,date_precision:typed.date_precision,quantitative_unit:typed.quantitative_unit,impact_basis:typed.impact_basis,validation_state:'NOT_REVIEWED',source_described_type:typed.source_described_type||null,...(family==='ATTACK_TO_EFFECT_CAUSATION'?{attack_claim_id:value(fd,'attack_claim_id')||null,effect_claim_id:value(fd,'effect_claim_id')||null}:{})},distinct_reason:required(fd,'distinct_reason','why this is a different fact'),evidence};
}

function facilityName(f){return f.canonical_name||f.working_name||f.name||'Working facility name';}
function facilityType(f){return ({hospital:'Hospital',primary_health_care_center:'Primary health care center',primary_health_care_center_medical_clinic:'Primary health care center / medical clinic'})[f.facility_type]||f.facility_type||'Type not yet established';}
function facilityDescription(f){return f.source_described_type||f.source_described_types?.working||f.source_described_types?.healthcare||f.source_described_types?.amenity||null;}
function facilityLocality(f){return f.locality||Object.values(f.locality_governorate||{}).filter(Boolean).join(' · ')||'Location not yet established';}
const facilityTypes=[['','Type not yet established'],['hospital','Hospital'],['primary_health_care_center','Primary health care center'],['primary_health_care_center_medical_clinic','Primary health care center / medical clinic']];
const coordinateMethods=['EXACT_POINT','ENTRANCE','MAPPED_FACILITY_POINT','POLYGON_CENTROID','POLYGON_FIRST_VERTEX','APPROXIMATE_LOCALITY','UNKNOWN'];
const coordinateReferences=[['MANUAL_NON_HDX','Manual researched point — no HDX match required'],['HDX_DERIVED','Original HDX-derived working coordinate'],['RESEARCHED_CORRECTION','Researched correction to an earlier coordinate']];
function sourceScopeFields(prefix='facility-source'){
 return `<fieldset class="section-space" data-source-scopes><legend>What does this source help establish?</legend>${guidance(prefix+'-scope','<b>Select only what this source actually helps establish:</b> identity, facility type, location, or a combination. One source does not automatically prove all three.')}<div class="choice-row">${[['identity','Facility identity'],['type','Facility type'],['location','Facility location']].map(([v,t])=>`<label><input type="checkbox" name="${h(prefix)}-scope" value="${v}"><span>${t}</span></label>`).join('')}</div></fieldset>`;
}
export function readFacilitySourceScopes(form,prefix='facility-source'){
 const fd=data(form),scopes=[...new Set(fd.getAll(prefix+'-scope').map(String))];
 if(!scopes.length||scopes.some(x=>!['identity','type','location'].includes(x)))throw Error('Choose what this source helps establish: identity, type, location, or more than one.');
 return scopes;
}
function manualStepper(step){return `<div class="manual-stepper" data-manual-stepper>${['1 Facility','2 Check existing','3 Describe record','4 Facts + evidence','5 Review changes'].map((t,i)=>`<span data-step="${i+1}" class="${i+1===step?'active':''}">${t}</span>`).join('')}</div>`;}
export function manualForm(facilities=[],options={}){
 const selected=options.prefillFacilityId||'',incidents=options.incidents||[],links=options.links||[],step=selected?2:1;
 const cards=facilities.map(f=>`<article class="facility-choice" data-facility-option="${h(f.facility_id)}"><div><b>${h(facilityName(f))}</b><span>${h(facilityType(f))} · ${h(facilityLocality(f))}</span>${facilityDescription(f)?`<small>Source describes it as: ${h(facilityDescription(f))}</small>`:''}<small>Alternate names: ${h((f.aliases||[]).map(a=>a.value||a).join('; ')||'None recorded')}</small></div><button class="primary" type="button" data-use-facility="${h(f.facility_id)}">Use this facility</button></article>`).join('');
 return `<form id="manual-form" data-form-kind="manual" data-manual-step="${step}">${intakeGuidance()}${manualStepper(step)}<p class="subtle">Nothing is shared until you review and submit. Dates, coordinates and unsupported details may remain unknown.</p>
 <section data-manual-pane="1" ${step===1?'':'hidden'}><h3>Find the facility first</h3>${guidance('manual-facility-search','<b>Search first.</b> Check similar names, alternate spellings, and nearby facilities before adding a new record. Choose an existing record when it is the same physical place.')}${help('manual-facility-match','What if the names look similar?','<p>Similar names are not proof of the same place. Check type, location, and alternate names. Only add a new facility if you cannot identify the same physical facility in the existing list; choose Not sure yet when evidence is insufficient.</p>')}${field('Search current facilities by name, alternate name or locality',input('facility_search','','search','data-facility-search placeholder="Start typing a facility name…"'))}<div class="facility-choices" data-facility-matches>${cards||'<p class="empty">No facility is recorded yet.</p>'}</div>${field('Selected facility',select('facility_id',[['','No existing facility selected'],...facilities.map(f=>[f.facility_id,facilityName(f)+' · '+facilityType(f)])],selected,'data-facility-choice'))}
 <details class="secondary-details" data-new-facility-details><summary>+ Add new facility — only when no existing facility matches</summary><div class="secondary-content"><fieldset data-new-facility data-required-text-scope ${selected?'disabled hidden':''}>${guidance('new-facility-verification','<b>Verify the facility itself.</b> Look for evidence of its identity, type, and location. If you cannot determine whether it matches another record, choose Not sure yet.')}<div class="form-grid section-space">${field('Facility working name',input('working_name','','text',requiredText),true)}${field('Proposed facility type — remains unreviewed',select('facility_type',facilityTypes))}${field('Source describes this facility as',input('source_described_type','','text',requiredText+' placeholder="For example: pharmacy, emergency medical center, or Unknown"'))}${field('Locality',input('locality','','text',requiredText))}${field('Governorate / region',input('region'))}${field('Known alternate names — one per line',area('aliases'))}${field('Known address / location description',area('location'))}</div><p class="subtle">Optional source-backed coordinates can be entered on the next step, after checking for existing records.</p><div class="form-grid">${field('Does this match an existing physical facility?',select('duplicate_disposition',[['unsure','Not sure yet — keep identity under review'],['different','Different physical facility — create separately']],'unsure'))}${field('Explain the identity comparison',area('duplicate_reason'))}</div>${guidance('new-facility-location','<b>Location not yet reviewed.</b> Typing a locality or coordinates is a proposal, not a location review. Coordinates can remain unknown.',{warn:true})}<label class="section-space"><input type="checkbox" name="include_identity_source" data-identity-source-toggle> Add evidence about this facility</label><fieldset data-identity-source disabled hidden>${sourceScopeFields('facility-source')}${renderSource('identity-source')}</fieldset><p class="subtle">Working identity and type remain unreviewed. A source-described term does not expand the reviewed type vocabulary.</p><button type="button" class="primary" data-manual-next="2" data-propose-facility data-required-text-submit>Use proposed new facility</button></fieldset></div></details>
 <div class="dialog-actions"><span class="subtle">Existing-facility search precedes new-facility entry.</span><button type="button" data-manual-next="2">Continue with selected facility</button></div></section>
 <section data-manual-pane="2" ${step===2?'':'hidden'}><h3>Check existing records first</h3><details class="secondary-details"><summary>Optional facility coordinates — existing or new facility</summary><label><input type="checkbox" name="include_location_proposal" data-location-proposal-toggle> Add missing coordinates or propose a source-backed correction</label><fieldset data-manual-location-proposal disabled hidden>${locationProposalFields({},options.sources||[],"manual-location-source")}</fieldset></details><div class="callout warning"><b>Possible existing records</b><br>Is the evidence about one of these incidents? Inspect before creating a separate record. Nothing is merged automatically.</div><div class="existing-incidents" data-existing-incidents></div><div class="form-grid section-space">${field('Record / event type',select('working_type',[['','Choose the episode type…'],['kinetic episode','Strike event'],['combined supported causal episode','Attack-and-effect episode'],['operational episode','Operational-status episode'],['service observation','Service / follow-up observation']],''))}<div class="field full">${renderDate('incident-date',{},'Proposed event / observation date')}</div></div><details class="secondary-details"><summary>Optional episode details</summary><div class="form-grid">${field('Attack relationship — if relevant',select('working_relationship',[['','Unknown / not established'],['EXACT_TARGET','Exact target'],['NEARBY_CONTEXT','Nearby / context']]))}${field('Working description of what was affected — not verified',input('affected_object'))}</div></details><div class="callout conflict section-space" data-incident-duplicate hidden><b>Possible duplicate incident</b><p data-incident-duplicate-text></p><p>Open the existing record, or explain why this is a separate incident. No automatic merge occurs.</p><label><input type="checkbox" name="different_record"> I inspected the possible match and intend to create a separate incident.</label></div>${field('Why this is a separate incident / episode',area('incident_distinct_reason'),true)}<div class="dialog-actions"><button type="button" data-manual-back="1">Back</button><button type="button" class="primary" data-manual-next="3" data-required-text-submit>Create a separate incident</button></div></section>
 <section data-manual-pane="3" hidden><h3>Describe the incident</h3><div class="form-grid">${field('What happened? Use a short neutral description.',area('incident_label','','required'),true)}${field('Episode structure',select('episode_structure',[['single','Single discrete event'],['repeated','Repeated / multiple attacks'],['unknown','Unknown']],'unknown'))}${field('Working notes / open questions',area('incident_notes'),true)}</div><div class="callout warning section-space"><b>Keep separate events separate.</b><br>Create one incident for each supported strike date. If the evidence cannot distinguish repeated attacks, retain one repeated episode.</div><p class="subtle">Next, add facts and evidence using the usual incident controls. A neutral description, a facility choice and an explicit episode type are needed to continue. Unknown dates and effects stay unknown. You can save privately at any step.</p><div class="dialog-actions"><button type="button" data-manual-back="2">Back</button><button class="primary" type="submit">Continue to facts</button></div></section><div class="dialog-actions"><button type="button" data-action="save-intake-draft">Save private draft</button><span class="subtle">Only you can see this draft. No facility or incident is created.</span></div><p class="form-error" role="alert" hidden></p><script type="application/json" data-manual-records>${JSON.stringify({incidents,links}).replaceAll('<','\\u003c')}</script></form>`;
}
function readNewFacility(fd){
 const name=required(fd,'working_name','the facility’s working name'),sourceType=required(fd,'source_described_type','its source-described type or Unknown'),locality=required(fd,'locality','the locality or Unknown'),lat=value(fd,'latitude'),lon=value(fd,'longitude');
 if((lat&&!lon)||(!lat&&lon))throw Error('Provide both facility coordinates, or leave both unknown.');
 if(lat&&(!Number.isFinite(Number(lat))||!Number.isFinite(Number(lon))||Math.abs(Number(lat))>90||Math.abs(Number(lon))>180))throw Error('Use valid latitude (−90 to 90) and longitude (−180 to 180).');
 if(lat&&Number(lat)===0&&Number(lon)===0)throw Error('Do not use 0,0 for an unknown facility location. Leave both coordinates blank.');
 const disposition=value(fd,'duplicate_disposition');if(!['different','unsure'].includes(disposition))throw Error('Record whether this is a different physical facility or remains uncertain.');
 const reason=value(fd,'duplicate_reason');if(disposition==='different'&&!reason)throw Error('Explain why this is a different physical facility.');
 const mapped=value(fd,'facility_type');if(!facilityTypes.some(([v])=>v===mapped))throw Error('Choose an approved facility type or leave it not established.');
 return {working_name:name,canonical_name:null,facility_type:mapped||null,source_described_type:sourceType,locality,region:value(fd,'region')||null,aliases:value(fd,'aliases').split('\n').map(x=>x.trim()).filter(Boolean),location:value(fd,'location')||null,identity_status:'UNNAMED_IDENTITY_UNRESOLVED',location_review_state:'NOT_REVIEWED',duplicate_disposition:disposition,duplicate_reason:reason||null,geo:lat?{latitude:Number(lat),longitude:Number(lon),source:required(fd,'coordinate_basis','the coordinate source'),method:value(fd,'coordinate_method')||'UNKNOWN',precision:required(fd,'coordinate_precision','coordinate precision'),limitations:required(fd,'coordinate_limits','coordinate precision and limitations')}:null};
}
export function readManual(form){
 const fd=data(form),existing=value(fd,'facility_id')||null,date=readDate(fd,'incident-date'),label=required(fd,'incident_label','a neutral incident description'),working=value(fd,'working_type');
 if(!['kinetic episode','combined supported causal episode','operational episode','service observation','research lead'].includes(working))throw Error('Choose a working record type.');
 let facility=null,identityEvidence=null;const coordinateProposal=fd.has('include_location_proposal')?readLocationProposal(fd,{facility_id:existing},'manual-location-source'):null;
 if(!existing){facility=readNewFacility(fd);if(fd.has('include_identity_source'))identityEvidence={...readSource(fd,'identity-source'),scopes:readFacilitySourceScopes(fd)};}
 if(form?.querySelector?.('[data-incident-duplicate]')?.hidden===false&&(!fd.has('different_record')||!value(fd,'incident_distinct_reason')))throw Error('Inspect the possible incident match, confirm it is separate, and explain the difference.');
 return {facility_id:existing,facility,identityEvidence,coordinateProposal,incident:{incident_label:label,working_type:working,working_date:date,working_relationship:value(fd,'working_relationship')||null,affected_object:value(fd,'affected_object')||null,episode_structure:value(fd,'episode_structure')||'unknown',distinct_reason:value(fd,'incident_distinct_reason')||null,working_notes:value(fd,'incident_notes')||null},working_type:working};
}
function manualRecords(form){const info=JSON.parse(form.querySelector('[data-manual-records]')?.textContent||'{}'),fid=form.elements.facility_id.value,ids=new Set((info.links||[]).filter(l=>l.facility_id===fid&&l.is_current!==false).map(l=>l.incident_id));return (info.incidents||[]).filter(i=>ids.has(i.incident_id));}
function updateManualRecords(form){
 const records=manualRecords(form),list=form.querySelector('[data-existing-incidents]');
 list.innerHTML=records.map(i=>`<article class="existing-incident"><div><b>${h(i.comparison_label||i.event_start||i.event_end||'Date not established')}</b><span>${h(i.incident_label)}</span></div><button type="button" data-action="open" data-id="${h(i.incident_id)}">Add evidence to existing incident</button></article>`).join('')||'<div class="empty">No currently recorded incident was found for this facility.</div>';
 let date;try{date=readDate(form,'incident-date')}catch{return}
 const matches=records.filter(i=>comparisonOverlaps(i,date));
 form.querySelector('[data-incident-duplicate]').hidden=!matches.length;
 form.elements.incident_distinct_reason.toggleAttribute('data-required-text',matches.length>0);
 form.querySelector('[data-incident-duplicate-text]').textContent=matches.map(i=>`${i.comparison_label} — ${i.incident_label}`).join('; ');
}
function manualSetStep(form,step){form.dataset.manualStep=String(step);for(const pane of form.querySelectorAll('[data-manual-pane]'))pane.hidden=pane.dataset.manualPane!==String(step);for(const marker of form.querySelectorAll('[data-manual-stepper] [data-step]'))marker.className=Number(marker.dataset.step)===step?'active':Number(marker.dataset.step)<step?'done':'';if(step===2)updateManualRecords(form);form.querySelector('.form-error').hidden=true;}

function facilityHeader(f){return `<div class="review-context"><div><div class="label">Physical facility</div><div class="value"><b>${h(facilityName(f))}</b><br>${h(facilityType(f))} · ${h(facilityLocality(f))}${facilityDescription(f)?`<br>Source describes it as: ${h(facilityDescription(f))}`:''}</div></div></div>`;}
function evidenceChoice(prefix,sources=[],current={}){return `${field('Use an existing source, or enter another source',select(prefix+'-existing',[['','Enter a new source'],...sources.map(s=>[s.source_id,`${s.publisher_platform||'Publisher unknown'} — ${s.title||s.source_id}`])],current.source_id||'',`data-source-reuse="${h(prefix)}"`),true)}<fieldset data-new-source="${h(prefix)}" ${current.source_id?'hidden disabled':''}>${renderSource(prefix)}</fieldset><fieldset data-reused-source="${h(prefix)}" ${current.source_id?'':'hidden disabled'}>${guidance(prefix+'-reused-source-task','<b>Read the saved source and check this specific fact.</b> Record the relevant location, passage, and any limits for this review.')}${help(prefix+'-reused-relationship-help','What do these evidence relationships mean?','<p><b>Supports this finding:</b> evidence for the fact. <b>Challenges this finding:</b> evidence against it. <b>Qualifies this finding:</b> narrows what can be concluded. <b>Provides background:</b> background that does not directly establish the fact.</p>')}<div class="form-grid">${field('How does it relate to this review?',select(prefix+'-reuse-relationship',[['','Choose how this source relates to this fact…'],['SUPPORTS','Supports this finding'],['CONTRADICTS','Challenges this finding'],['LIMITS','Qualifies this finding'],['CONTEXT_ONLY','Provides background']],'','required'))}${field('Where exactly is the relevant evidence?',input(prefix+'-reuse-locator','','text','required'))}${field('Relevant passage / description',area(prefix+'-reuse-excerpt','','required'),true)}${field('Important limitations',area(prefix+'-reuse-limits','','required'),true)}</div></fieldset>`;}
function readEvidenceChoice(form,prefix){const fd=data(form),id=value(fd,prefix+'-existing');if(!id)return readSource(fd,prefix);if(!['SUPPORTS','CONTRADICTS','LIMITS','CONTEXT_ONLY'].includes(value(fd,prefix+'-reuse-relationship')))throw Error('Choose how the source relates to this fact.');return {source_id:id,relation:{support_direction:value(fd,prefix+'-reuse-relationship'),directness:null,originality:'unknown',dependency_group_id:null,dependency_provenance:{relies_on:'unknown',underlying:null,independence:null},evidence_locator:[{locator:required(fd,prefix+'-reuse-locator','the exact evidence location'),excerpt:required(fd,prefix+'-reuse-excerpt','the relevant passage or description')}],limitations:required(fd,prefix+'-reuse-limits','the limitations of this evidence')}};}
function locationFields(initial={},coordinatesRequired=false){
 const geo=Object.hasOwn(initial,'coordinates')?(initial.coordinates||{}):(initial.geo||{}),locality=Object.hasOwn(initial,'locality')?initial.locality:Object.values(initial.locality_governorate||{}).filter(Boolean).join(' · '),recorded=key=>Object.hasOwn(initial,key)?initial[key]:geo[key],method=recorded('method')??'UNKNOWN',methods=coordinateMethods.includes(method)?coordinateMethods:[...coordinateMethods,[method,method+' (recorded method)']];
 return `<div class="form-grid">${field('Facility locality / address',input('location_locality',locality||''),true)}${field(coordinatesRequired?'Facility latitude':'Facility latitude — leave blank if unknown',input('location_latitude',geo.latitude??'','number','step="any" min="-90" max="90"'+(coordinatesRequired?' '+requiredText:'')))}${field(coordinatesRequired?'Facility longitude':'Facility longitude — leave blank if unknown',input('location_longitude',geo.longitude??'','number','step="any" min="-180" max="180"'+(coordinatesRequired?' '+requiredText:'')))}${field('How was the location determined?',select('location_method',methods,method))}${field('Location precision',input('location_precision',recorded('precision')??'','text',requiredText))}${field('Location limitations',area('location_limitations',recorded('limitations')??'',requiredText),true)}</div>${guidance('facility-coordinate-scope','These are facility coordinates, not strike coordinates. Leave missing coordinates blank; do not enter 0,0 as a placeholder.',{warn:true})}`;
}
function readLocationFields(form){const fd=data(form),lat=value(fd,'location_latitude'),lon=value(fd,'location_longitude');if((lat&&!lon)||(!lat&&lon))throw Error('Provide both facility coordinates or leave both blank.');if(lat&&(!Number.isFinite(Number(lat))||!Number.isFinite(Number(lon))||Math.abs(Number(lat))>90||Math.abs(Number(lon))>180))throw Error('Use valid facility coordinates.');if(lat&&Number(lat)===0&&Number(lon)===0)throw Error('Leave unknown coordinates blank; do not use 0,0.');return {locality:value(fd,'location_locality')||null,coordinates:lat?{latitude:Number(lat),longitude:Number(lon),crs:value(fd,'location_crs')||'UNKNOWN'}:null,method:value(fd,'location_method')||'UNKNOWN',precision:required(fd,'location_precision','location precision or Unknown'),limitations:required(fd,'location_limitations','location limitations'),coordinate_reference_type:value(fd,'location_reference_type')||'MANUAL_NON_HDX',source_evidence_version:value(fd,'location_source_version')||null,researcher_explanation:value(fd,'location_explanation')||null};}
function geographicProvenanceFields(initial={}){return `<div class="form-grid section-space">${field('Coordinate reference system',select('location_crs',[['UNKNOWN','Unknown — cannot export as GIS point'],['EPSG:4326','WGS84 decimal degrees (EPSG:4326)']],initial.coordinates?.crs||initial.geo?.crs||'UNKNOWN'))}${field('Coordinate provenance',select('location_reference_type',coordinateReferences,initial.coordinate_reference_type||'MANUAL_NON_HDX'))}${field('Evidence date / version — where known',input('location_source_version',initial.source_evidence_version||''))}${field('Explain why this point is the actual physical healthcare facility',area('location_explanation',initial.researcher_explanation||'','required'),true)}</div><p class="subtle">No HDX identifier is required for a manual point. Existing HDX records stay preserved. A village centroid or a similarly named facility is not sufficient evidence.</p>`;}
function locationProposalFields(facility={},sources=[],prefix='location-proposal-source'){return `${locationFields(facility,true)}${geographicProvenanceFields(facility)}<h3>Geographic source and evidence</h3>${evidenceChoice(prefix,sources)}<label><input type="checkbox" name="location_proposal_attestation" required> I am submitting source-backed geographic evidence; this remains pending supervisor geographic review.</label>`;}
export function locationProposalForm(facility,sources=[]){const pending=(facility.location_evidence||[]).filter(x=>x.scope==='location'&&x.location).at(-1),review=facility.location_review,initial={...facility,...(pending&&(!review?.reviewed_at||Date.parse(pending.entered_at)>Date.parse(review.reviewed_at))?pending.location:review||{})};initial.coordinate_reference_type=(initial.coordinates||initial.geo)?'RESEARCHED_CORRECTION':'MANUAL_NON_HDX';return `<form id="location-proposal-form" data-form-kind="location-proposal">${facilityHeader(facility)}<p>Enter missing coordinates or propose a correction. The same physical facility point is shared by all linked incidents. Do not enter guessed coordinates.</p>${locationProposalFields(initial,sources)}<p class="form-error" role="alert" hidden></p><div class="dialog-actions"><button class="primary" type="submit">Review coordinate proposal</button></div></form>`;}
export function readLocationProposal(form,facility={},prefix='location-proposal-source'){const fd=data(form),location=readLocationFields(fd);if(!location.coordinates)throw Error('Enter a known facility coordinate pair, or use Add facility evidence to document an unknown location.');if(!fd.has('location_proposal_attestation'))throw Error('Confirm that this coordinate is a proposal awaiting geographic review.');if(!location.researcher_explanation)throw Error('Explain how the evidence identifies this physical facility.');return {facility_id:facility.facility_id,scopes:['location'],location,...readEvidenceChoice(fd,prefix)};}
export function facilityAssociationForm(facility,link,sources=[],identityClaims=[]){return `<form id="facility-association-form" data-form-kind="facility-association" data-link="${h(link.incident_facility_id)}" data-incident="${h(link.incident_id)}">${facilityHeader(facility)}<p><b>Review this exact incident’s physical facility association.</b> This does not establish an attack, causation, geographic accuracy, or factual approval. Current incident: ${h(link.incident_id)}. Current association: ${h(link.facility_match_state || 'unresolved')}.</p><div class="form-grid">${field('Does this incident record refer to this exact physical facility?',select('association_state',[['unresolved','Not established / needs investigation'],['supported','Evidence supports this exact physical facility']],'unresolved'))}${field('Current canonical physical-identity finding',select('association_identity_claim',[['','Choose the reviewed physical identity finding…'],...identityClaims.filter(c=>c.facility_id===facility.facility_id&&c.claim_family==='IDENTITY'&&c.identity_purpose!=='facility_comparison').map(c=>[c.claim_id,c.subject])]))}${field('Explain the exact incident-to-facility source evidence',area('association_basis','','required'),true)}${field('Supervisor review note and limitations',area('association_note','','required'),true)}</div><h3>Evidence for this physical association</h3>${evidenceChoice('association-source',sources)}<label><input type="checkbox" name="association_attestation" required> I reviewed this exact incident–facility association. Similar names, coordinates or incident approval alone do not establish it.</label><p class="form-error" role="alert" hidden></p><div class="dialog-actions"><button class="primary" type="submit">Review physical association decision</button></div></form>`;}
export function readFacilityAssociation(form,facility={},link={}){const fd=data(form),state=value(fd,'association_state'),cid=value(fd,'association_identity_claim');if(!['supported','unresolved'].includes(state))throw Error('Choose whether this exact physical association is established.');if(state==='supported'&&!cid)throw Error('Choose the current reviewed physical-identity finding.');if(!fd.has('association_attestation'))throw Error('Confirm that you reviewed this exact physical facility association.');const evidence=readEvidenceChoice(fd,'association-source');if(state==='supported'&&evidence.relation.support_direction!=='SUPPORTS')throw Error('An established association needs evidence that supports this exact physical link.');return {facility_id:facility.facility_id,incident_id:link.incident_id,incident_facility_id:link.incident_facility_id,facility_match_state:state,identity_claim_id:cid||null,basis:required(fd,'association_basis','the source-backed physical association explanation'),review_note:required(fd,'association_note','your association review note'),attestation:true,...evidence};}
export function facilityResolutionForm(facility,facilities=[],sources=[]){
 return `<form id="facility-resolution-form" data-form-kind="facility-resolution">${facilityHeader(facility)}${guidance('facility-duplicate-task','<b>Decide whether these records refer to the same physical facility, not whether their names look similar.</b> If the evidence is insufficient, choose Not sure yet.',{warn:true})}${help('facility-duplicate-outcome','What does this decision change?','<p>An evidence-backed Same physical facility decision links current incidents to the existing facility. The provisional record, names, evidence, and history remain preserved. Different physical facility keeps separate records; Not sure yet leaves the comparison unresolved. Nothing is merged automatically.</p>')}<div class="form-grid section-space">${field('What does the comparison establish?',select('facility_outcome',[['unsure','Not sure yet'],['same','Same physical facility'],['different','Different physical facility']],'unsure'))}${field('Compare with this existing facility',select('target_facility_id',[['','Choose the facility being compared…'],...facilities.filter(f=>f.facility_id!==facility.facility_id).map(f=>[f.facility_id,`${facilityName(f)} · ${facilityLocality(f)}`])]))}${field('Evidence / basis for this comparison',area('facility_basis','','required'),true)}${field('Human review note',area('facility_review_note','','required'),true)}</div><h3 class="section-space">Evidence for this identity decision</h3><div class="callout section-space"><b>Comparison proposition:</b> This provisional record and the selected existing record describe the <b>same physical facility</b>.<p>For Same physical facility, the source must support that proposition. For Different physical facility, choose Challenges this finding or Qualifies this finding. Not sure yet can preserve any accurately recorded relationship.</p></div>${evidenceChoice('resolution-source',sources).replace('How does this relate to the fact?','Relationship to the same-physical-facility proposition').replace('How does it relate to this review?','Relationship to the same-physical-facility proposition')}<div class="certification-box"><label><input type="checkbox" name="facility_attestation" required> I reviewed the identity evidence and the physical-facility comparison.</label></div><p class="form-error" role="alert" hidden></p><div class="dialog-actions"><span class="subtle">Review the proposed decision before submitting.</span><button class="primary" type="submit">Review facility resolution</button></div></form>`;
}
export function readFacilityResolution(form,facility={}){const fd=data(form),outcome=value(fd,'facility_outcome'),target=value(fd,'target_facility_id')||null;if(!['same','different','unsure'].includes(outcome))throw Error('Choose Same physical facility, Different physical facility, or Not sure yet.');if(['same','different'].includes(outcome)&&!target)throw Error('Choose the existing physical facility used in this comparison.');if(target&&target===facility.facility_id)throw Error('Compare with a different record, not the same facility record.');if(!fd.has('facility_attestation'))throw Error('Confirm that you reviewed the physical-facility identity evidence.');const basis=required(fd,'facility_basis','the evidence/basis for the comparison'),review_note=required(fd,'facility_review_note','your review note'),evidence=readEvidenceChoice(fd,'resolution-source'),direction=evidence.relation.support_direction;if(outcome==='same'&&direction!=='SUPPORTS')throw Error('Same physical facility requires evidence that Supports the same-physical-facility proposition.');if(outcome==='different'&&!['CONTRADICTS','LIMITS'].includes(direction))throw Error('Different physical facility requires evidence that Contradicts or Limits the proposition that these records describe the same place.');return {facility_id:facility.facility_id,outcome,target_facility_id:target,basis,review_note,attestation:true,...evidence};}
export function facilityIdentityReopenForm(facility, resolution, target = null) {
 return `<form id="facility-identity-reopen-form" data-form-kind="facility-identity-reopen" data-resolution="${h(resolution.id)}">${facilityHeader(facility)}<h2>Reopen Facility Identity Decision</h2><p><b>Earlier decision:</b> Same physical facility as ${h(target ? facilityName(target) : resolution.target_facility_id)}.</p><p class="subtle">${h(resolution.reviewer || 'Reviewer not recorded')} · ${h(resolution.reviewed_at || 'Time not recorded')}. This earlier decision stays in history.</p><div class="callout warning"><b>Identity will return to Needs review.</b><p>This does not declare the facilities different. The normal evidence-backed identity workflow will determine Same physical facility, Different physical facility, or Not sure yet.</p><p>Earlier aliases and incident associations remain preserved. Affected incident completion and Phase 2 approvals will require re-review.</p></div>${field('Why are you reopening this identity decision?', area('facility_reopen_reason', '', 'required maxlength="4000"'), true)}<div class="certification-box"><label><input type="checkbox" name="facility_reopen_attestation" required> I understand that this reopens identity review and preserves the earlier decision.</label></div><p class="form-error" role="alert" hidden></p><div class="dialog-actions"><span class="subtle">Review the affected records before submitting.</span><button class="primary" type="submit">Review identity reopening</button></div></form>`;
}
export function readFacilityIdentityReopen(form) {
 const fd = data(form), reason = required(fd, 'facility_reopen_reason', 'why this identity decision needs to be reopened');
 if (reason.length > 4000) throw Error('Keep the reason within 4,000 characters.');
 if (!fd.has('facility_reopen_attestation')) throw Error('Confirm that the earlier identity decision will remain in history.');
 return {reason};
}
export function locationForm(facility,sources=[],current=facility.location_review||{}){
 return `<form id="location-review-form" data-form-kind="location-review">${facilityHeader(facility)}${guidance('facility-location-task','<b>Check the evidence for this physical facility’s location.</b> Only a supervisor can accept the geographic point. Check the physical facility identity, source, coordinate method and limitations. Incident and fact approval remain separate.')}${locationFields({...facility,...current})}${geographicProvenanceFields({...facility,...current})}<div class="form-grid section-space">${field('What does the location evidence establish?',select('location_review_state',[['NEEDS_MORE_EVIDENCE','Requires further investigation'],['SUPPORTED','Accept this physical facility point'],['CONFLICTING','Disputed — conflicting evidence'],['REJECTED','Reject proposed coordinate — evidence does not establish this point']],current.review_state||current.state||'NEEDS_MORE_EVIDENCE'))}${field('Evidence / method basis',area('location_basis',current.basis||'','required'),true)}${field('Human review note',area('location_review_note',current.review_note||'','required'),true)}</div><h3 class="section-space">Evidence for this location review</h3>${evidenceChoice('location-source',sources,current)}<div class="certification-box"><label><input type="checkbox" name="location_attestation" required> I checked the facility location, precision, evidence and limitations.</label></div><p class="form-error" role="alert" hidden></p><div class="dialog-actions"><span class="subtle">Location can remain conflicting or unknown.</span><button class="primary" type="submit">Review location decision</button></div></form>`;
}
export function readLocation(form,facility={}){const fd=data(form),choice=value(fd,'location_review_state'),review_state=choice==='REJECTED'?'NEEDS_MORE_EVIDENCE':choice;if(!['SUPPORTED','CONFLICTING','NEEDS_MORE_EVIDENCE'].includes(review_state))throw Error('Choose a location evidence state.');if(!fd.has('location_attestation'))throw Error('Confirm that you checked the location evidence.');const location=readLocationFields(fd);if(review_state==='SUPPORTED'&&(!location.coordinates||location.coordinates.crs!=='EPSG:4326'))throw Error('Accepting a point requires known WGS84 decimal-degree coordinates.');if(review_state==='SUPPORTED'&&['UNKNOWN','APPROXIMATE_LOCALITY'].includes(location.method))throw Error('An accepted point must identify the physical facility, not an approximate locality.');if(!location.researcher_explanation)throw Error('Explain how the source identifies the physical facility.');return {facility_id:facility.facility_id,...location,coordinate_rejected:choice==='REJECTED',review_state,basis:required(fd,'location_basis','the location evidence basis'),review_note:required(fd,'location_review_note','your location review note'),attestation:true,...readEvidenceChoice(fd,'location-source')};}
function facilityScopeClaimFields(facility,claims){
 const current=claims.filter(c=>c.facility_id===facility.facility_id&&c.is_current!==false);
 return [['identity','IDENTITY','Facility identity',['BOOLEAN','TEXT_WHERE_REQUIRED']],['type','FACILITY_TYPE','Facility type',null]].map(([scope,family,name,types])=>{const choices=current.filter(c=>c.claim_family===family&&c.identity_purpose!=='facility_comparison'&&(!types||types.includes(c.value_type)));return `<fieldset data-claim-scope="${scope}" hidden disabled><legend>${name} proposition</legend>${choices.length?field('Link this source to the exact existing fact',select('facility_'+scope+'_claim',[['','Choose the fact this source addresses…'],...choices.map(c=>[c.claim_id,c.subject])],choices.length===1?choices[0].claim_id:'','required')):'<p>No current fact is available for this dimension. The submission must create or identify the proper proposition before linking evidence.</p>'}</fieldset>`;}).join('');
}
export function facilityEvidenceForm(facility,sources=[],claims=[]){return `<form id="facility-evidence-form" data-form-kind="facility-evidence">${facilityHeader(facility)}${sourceScopeFields()}${facilityScopeClaimFields(facility,claims)}<fieldset data-location-scope hidden disabled><h3>Facility location described by this source</h3>${locationFields(facility)}${geographicProvenanceFields(facility)}<p class="subtle">Adding a location source does not certify the location.</p></fieldset>${evidenceChoice('facility-evidence-source',sources)}<p class="form-error" role="alert" hidden></p><div class="dialog-actions"><span class="subtle">The source links only to the dimensions you selected.</span><button class="primary" type="submit">Review facility evidence</button></div></form>`;}
export function readFacilityEvidence(form,facility={}){const fd=data(form),scopes=readFacilitySourceScopes(fd),links={};for(const scope of ['identity','type'])if(scopes.includes(scope)&&fd.has('facility_'+scope+'_claim'))links[scope+'_claim_id']=required(fd,'facility_'+scope+'_claim','the exact '+scope+' proposition this source addresses');return {facility_id:facility.facility_id,scopes,...links,...readEvidenceChoice(fd,'facility-evidence-source'),...(scopes.includes('location')?{location:readLocationFields(fd)}:{})};}

export function taskForm(gap={}){
 const state=gap.lab_task_state||'NOT_ASSESSED',disposition=gap.task_disposition||gap.disposition;
 const choice=state==='NOT_ASSESSED'?'unspecified':state==='RESOLVED'?'resolved':state==='UNABLE_TO_RESOLVE'?'unable':state==='DEFERRED'?'deferred':state==='BLOCKED'?'blocked':disposition==='ready_for_review'||/^Ready for factual review — /.test(gap.next_action||'')?'ready':/^Search outside sources — /.test(gap.next_action||'')?'outside':/^Check preserved evidence — /.test(gap.next_action||'')?'preserved':'active';
 const instruction=gap.next_action||(state==='NOT_ASSESSED'?gap.historical_next_action:'')||'';
 return `<form id="task-form" data-form-kind="task"><h2>What still needs checking</h2>${guidance('task-decision','<b>Describe the question that needs research or clarification.</b> Say what is missing, what the researcher should look for, why it matters, and the current lab status.')}${field('What is unclear or missing?',area('factual_question',gap.factual_question||'','required'),true)}${field('Why does it matter?',area('reason',gap.reason||gap.historical_reason||'','required'),true)}${field('What should the researcher look for or check?',area('next_action',instruction,'required'),true)}${field('Current lab status',select('task_disposition',[['unspecified','Not yet assessed by the lab'],['active','Active — research work required'],['blocked','Blocked — cannot proceed yet'],['preserved','Active — check preserved evidence'],['outside','Active — search outside sources'],['ready','Active — ready for factual review'],['deferred','Deferred — no active search now'],['unable','Unable to resolve with available evidence'],['resolved','Resolved']],choice))}${field('Decision / resolution notes',area('resolution',state==='NOT_ASSESSED'?'':gap.resolution||gap.lab_task_reason||'',choice==='unspecified'?'':requiredText),true)}${guidance('task-deferred-unknown','<b>Deferred does not mean resolved.</b> The question is not being actively researched now. Unable to resolve means the available research did not establish an answer; it is not a factual No.',{warn:true})}${help('task-status-help','How should I choose the next step?','<p>Use Check preserved evidence when the next step is to inspect saved sources. Use Search outside sources only when that research is actually required. Needs More Evidence describes a finding; it does not itself assign an outside search. Deferred and unable-to-resolve tasks stay visible but are not counted as active work.</p>')}<details class="secondary-details"><summary>Previous research task history</summary><div class="secondary-content"><p><b>Previous research disposition:</b> ${h(gap.historical_disposition||gap.historical_status||'Not recorded')}</p><p>${h(gap.historical_resolution||'No previous resolution note recorded.')}</p><p><b>Previous research instruction:</b> ${h(gap.historical_next_action||'Not recorded')}</p><p class="subtle">The preserved question and guidance are material to assess. Previous decisions do not activate or defer current lab work.</p></div></details><p class="form-error" role="alert" hidden></p><button class="primary" type="submit">Add task decision to changes</button></form>`;
}
export function readTask(form,gap={}){
 const fd=data(form),d=value(fd,'task_disposition'),map={unspecified:['open','active','NOT_ASSESSED'],active:['open','active','ACTIVE'],blocked:['blocked','blocked','BLOCKED'],preserved:['open','active','ACTIVE'],outside:['open','active','ACTIVE'],ready:['in progress','ready_for_review','ACTIVE'],deferred:['deferred','deferred','DEFERRED'],unable:['deferred','unable_to_resolve','UNABLE_TO_RESOLVE'],resolved:['resolved','resolved','RESOLVED']};
 if(!map[d]||d==='unspecified')throw Error('Choose a current lab task decision before adding changes.');const resolution=value(fd,'resolution')||null;
 if(d!=='unspecified'&&!resolution)throw Error('Explain why this current lab task decision is appropriate.');
 const instruction=required(fd,'next_action','what should be checked next'),prefix={preserved:'Check preserved evidence — ',outside:'Search outside sources — ',ready:'Ready for factual review — '}[d];
 const nextAction=prefix?prefix+instruction.replace(/^(Check preserved evidence|Search outside sources|Ready for factual review) — /,''):instruction;
 return {task:{gap_task_id:gap.gap_task_id||null,claim_id:gap.claim_id||null,factual_question:required(fd,'factual_question','what is unclear'),reason:required(fd,'reason','why this research question matters'),next_action:nextAction,status:map[d][0],disposition:map[d][1],lab_task_state:map[d][2],lab_task_reason:resolution,resolution}};
}

function updateSourceRequirements(section) {
 const prefix=section.dataset.sourcePrefix, fields=section.closest('form')?.elements;
 const field=name=>fields?.namedItem(prefix+'-'+name);
 field('underlying')?.toggleAttribute('data-required-text',field('relies')?.value==='yes');
 field('material-reason')?.toggleAttribute('data-required-text',field('relationship')?.value==='LIMITS'&&!field('material')?.checked);
}

export function syncSourceRequirements(root) {
 for(const section of root.querySelectorAll('[data-source-prefix]'))updateSourceRequirements(section);
}

const bound=new WeakSet();
export function bindForm(root){
 if(!root)return;
 syncSourceRequirements(root);
 for(const form of root.querySelectorAll('[data-form-kind="manual"]'))if(form.dataset.manualStep==='2')updateManualRecords(form);
 if(bound.has(root))return;bound.add(root);
 // Native validation runs before submit. Reveal the first invalid control,
 // including one in a closed disclosure, instead of silently blocking Save.
 root.addEventListener('invalid',event=>{
  const control=event.target,form=control.form;
  if(!form)return;
  event.preventDefault();
  const invalid=[...form.elements].filter(el=>el.willValidate&&!el.validity.valid);
  for(const el of invalid)for(let parent=el.parentElement;parent&&parent!==form;parent=parent.parentElement)if(parent.tagName==='DETAILS')parent.open=true;
  const first=invalid[0];if(!first)return;
  let error=form.querySelector('.form-error');
  if(!error){error=form.ownerDocument.createElement('p');error.className='form-error';error.setAttribute('role','alert');}
  const label=first.labels?.[0]?.textContent?.trim()||first.name||'the required field';
  error.textContent='Check '+label+': '+(first.validationMessage||'Complete this field before continuing.');
  error.hidden=false;
  // Keep the actionable message beside its field, outside any wrapping label
  // so subsequent validation does not recursively include the error in its name.
  (first.closest('label')||first).insertAdjacentElement('afterend',error);
  first.focus();
  first.scrollIntoView?.({block:'center'});
  error.scrollIntoView?.({block:'nearest'});
 },true);
 root.addEventListener('toggle',event=>{const details=event.target;if(details.matches?.('[data-new-facility-details]')&&details.open){const form=details.closest('form');form.elements.facility_id.value='';const pane=form.querySelector('[data-new-facility]');pane.hidden=false;pane.disabled=false;}},true);
 root.addEventListener('change',event=>{
  const el=event.target;
  if(el.name==='validation_state'&&el.form?.dataset.approvalRationaleRequired==='true')
   el.form.elements.basis_explanation.required=el.value==='SUPPORTED';
  if(el.matches('[data-date-precision]')){const parent=el.closest('[data-date-prefix]');for(const part of parent.querySelectorAll('[data-date-kind]'))part.hidden=part.dataset.dateKind!==el.value;}
  if(el.matches('[data-source-kind]')){const parent=el.closest('[data-source-prefix]'),social=parent.querySelector('[data-social-fields]');if(social)social.hidden=el.value!=='social';}
  if(el.name?.endsWith('-relationship')){const parent=el.closest('[data-source-prefix]'),box=parent?.querySelector('[name$="-material"]');if(box&&['LIMITS','CONTRADICTS'].includes(el.value))box.checked=true;}
  const source=el.closest('[data-source-prefix]');
  if(source)updateSourceRequirements(source);
  if(el.name==='duplicate_disposition')el.form.elements.duplicate_reason.toggleAttribute('data-required-text',el.value==='different');
  if(el.name==='task_disposition')el.form.elements.resolution.toggleAttribute('data-required-text',el.value!=='unspecified');
  if(el.form?.id==='requirements-form'&&el.name.startsWith('disposition-'))
   el.form.elements.namedItem('reason-'+el.name.slice('disposition-'.length))?.toggleAttribute('data-required-text',!!el.value);
  if(el.matches('[data-facility-choice]')){const pane=el.form.querySelector('[data-new-facility]');pane.hidden=!!el.value;pane.disabled=!!el.value;updateManualRecords(el.form);}
  if(el.matches('[data-location-proposal-toggle]')){const pane=el.form.querySelector('[data-manual-location-proposal]');pane.hidden=!el.checked;pane.disabled=!el.checked;}
  if(el.matches('[data-identity-source-toggle]')){const pane=el.form.querySelector('[data-identity-source]');pane.hidden=!el.checked;pane.disabled=!el.checked;}
  if(el.matches('[data-new-fact-evidence-toggle]'))setInitialEvidence(el.form,el.checked);
  if(el.matches('[data-source-reuse]')&&el.dataset.sourceReuse){const prefix=el.dataset.sourceReuse,original=el.form.querySelector(`[data-new-source="${prefix}"]`),reuse=el.form.querySelector(`[data-reused-source="${prefix}"]`);if(original&&reuse){original.hidden=!!el.value;original.disabled=!!el.value;reuse.hidden=!el.value;reuse.disabled=!el.value;}}
  if(el.name==='facility-source-scope'){const scopes=[...el.form.querySelectorAll('[name="facility-source-scope"]:checked')].map(x=>x.value);for(const pane of el.form.querySelectorAll('[data-location-scope],[data-claim-scope]')){const enabled=scopes.includes(pane.hasAttribute('data-location-scope')?'location':pane.dataset.claimScope);pane.hidden=!enabled;pane.disabled=!enabled;}}
  if(el.form?.matches('[data-form-kind="manual"]')&&el.name?.startsWith('incident-date'))updateManualRecords(el.form);
  if(el.matches('[data-new-family], [data-duration-mode]')){
   const form=el.form,family=form.elements.claim_family.value,claims=JSON.parse(form.querySelector('[data-form-claims]')?.textContent||'[]');
   const existingMode=form.elements.duration_mode?.value||'date',duration=family==='RESTORATION_DATE'&&existingMode==='duration';
   const claim={claim_family:family,value_type:duration?'QUANTITATIVE':FAMILIES[family][1],proposed_value:null,quantitative_unit:duration?'days':null,impact_basis:duration?'directly reported':null};
   form.querySelector('[data-new-typed]').innerHTML=(family==='RESTORATION_DATE'?field('Record a date or a source-reported duration?',select('duration_mode',[['date','Restoration / end date'],['duration','Duration explicitly reported by a source']],duration?'duration':'date','data-duration-mode')):'')+renderTyped('new-fact',claim);
   form.querySelector('[data-cause-container]').innerHTML=causeFields(claim,claims);
  }
 });
 root.addEventListener('input',event=>{
  if(event.target.matches('[data-facility-search]')){const q=event.target.value.toLowerCase().trim();for(const card of event.target.form.querySelectorAll('[data-facility-option]'))card.hidden=q&&!card.textContent.toLowerCase().includes(q);}
  if(event.target.form?.matches('[data-form-kind="manual"]')&&event.target.name?.startsWith('incident-date'))updateManualRecords(event.target.form);
 });
 root.addEventListener('click',event=>{
  const sourceButton=event.target.closest('[data-add-initial-source],[data-remove-initial-source]');
  if(sourceButton){
   event.preventDefault();const form=sourceButton.form;if(!form?.matches('[data-form-kind="new-fact"]'))return;
   if(sourceButton.hasAttribute('data-add-initial-source')){const next=Number(form.dataset.nextSource)||2;form.dataset.nextSource=String(next+1);form.querySelector('[data-initial-sources]').insertAdjacentHTML('beforeend',initialSourceCard('new-source-'+next,next));}
   else sourceButton.closest('[data-initial-source]').remove();
   const sources=[...form.querySelectorAll('[data-initial-source]')];sources.forEach((source,index)=>source.querySelector('[data-initial-source-number]').textContent=String(index+1));
   if(!sources.length)setInitialEvidence(form,false);
   return;
  }
  const button=event.target.closest('[data-use-facility],[data-manual-next],[data-manual-back]');if(!button)return;event.preventDefault();const form=button.form;
  try{
   if(button.matches('[data-use-facility]')){form.elements.facility_id.value=button.dataset.useFacility;form.querySelector('[data-new-facility]').hidden=true;form.querySelector('[data-new-facility]').disabled=true;manualSetStep(form,2);return;}
   if(button.dataset.manualBack){manualSetStep(form,Number(button.dataset.manualBack));return;}
   const step=Number(button.dataset.manualNext);
   if(step===2){if(button.hasAttribute('data-propose-facility')){form.elements.facility_id.value='';form.querySelector('[data-new-facility]').disabled=false;readNewFacility(data(form));if(form.elements.include_identity_source.checked){readSource(form,'identity-source');readFacilitySourceScopes(form);}}else if(!form.elements.facility_id.value)throw Error('Choose an existing facility, or open Add new facility and describe it.');}
   if(step===3){readDate(form,'incident-date');if(!form.querySelector('[data-incident-duplicate]').hidden&&(!form.elements.different_record.checked||!form.elements.incident_distinct_reason.value.trim()))throw Error('Inspect the possible incident match, confirm it is separate, and explain the difference.');}
   manualSetStep(form,step);
  }catch(error){const notice=form.querySelector('.form-error');notice.textContent=error.message;notice.hidden=false;}
 });
}

export function captureIntake(form) {
 return {step:Number(form.dataset.manualStep)||1, fields:[...form.elements].filter(e=>e.name).map(e=>({name:e.name,value:e.value,checked:!!e.checked}))};
}
export function restoreIntake(form,saved) {
 const used=new Map();
 for(const item of saved.fields||[]){const fields=[...form.elements].filter(e=>e.name===item.name), index=used.get(item.name)||0,e=fields[index];used.set(item.name,index+1);if(!e)continue;e.value=item.value;if(['checkbox','radio'].includes(e.type))e.checked=item.checked;}
 const existing=!!form.elements.facility_id.value,pane=form.querySelector('[data-new-facility]');pane.hidden=existing;pane.disabled=existing;
 const source=form.querySelector('[data-identity-source]');source.hidden=!form.elements.include_identity_source.checked;source.disabled=source.hidden;
 if(!existing)form.querySelector('[data-new-facility-details]').open=true;
 for(const el of form.querySelectorAll('[data-date-precision]'))el.dispatchEvent(new Event('change',{bubbles:true}));
 form.elements.duplicate_reason.toggleAttribute('data-required-text',form.elements.duplicate_disposition.value==='different');
 syncSourceRequirements(form);
 manualSetStep(form,saved.step||1);
}
